   ```javascript
   const { Client, GatewayIntentBits } = require('discord.js');
   ```

5. Initialize a new Discord client with the bot token and required intents:

   ```javascript
   const client = new Client({
     intents: [
       GatewayIntentBits.Guilds,
       GatewayIntentBits.GuildMessages,
       GatewayIntentBits.MessageContent,
     ],
     partials: ['MESSAGE', 'CHANNEL', 'REACTION'],
   });

   client.login('YOUR_DISCORD_BOT_TOKEN');
   ```

6. Create a command handler to define the `ban` slash command:

   ```javascript
   const { SlashCommandBuilder } = require('discord.js');

   const data = new SlashCommandBuilder()
     .setName('ban')
     .setDescription('Bans a user from the server.')
     .addUserOption((option) =>
       option
         .setName('user')
         .setDescription('The user to ban.')
         .setRequired(true)
     );

   module.exports = data;
   ```

7. Create an event listener for the interactionCreate event to handle the `ban` command:

   ```javascript
   client.on('interactionCreate', async (interaction) => {
     if (!interaction.isCommand()) return;

     if (interaction.commandName === 'ban') {
       // Your ban logic here
     }
   });
   ```

8. Implement the ban logic in the interactionCreate event listener:

   ```javascript
   client.on('interactionCreate', async (interaction) => {
     if (!interaction.isCommand()) return;

     if (interaction.commandName === 'ban') {
       const { user } = interaction.options;

       // Check if the bot has permission to ban users
       if (!interaction.guild.members.me?.hasPermission('BAN_MEMBERS')) {
         return interaction.reply({
           content: 'I do not have permission to ban users.',
           ephemeral: true,
         });
       }

       // Check if the user is a guild member
       if (!interaction.guild.members.me?.kickable(user)) {
         return interaction.reply({
           content: 'I cannot ban that user.',
           ephemeral: true,
         });
       }

       // Ban the user
       await interaction.guild.members.ban(user, { days: 0, reason: 'Banned by command' });

       interaction.reply({
         content: `${user.tag} has been banned.`,
       });
     }
   });
   ```

9. Finally, export the Discord client to enable it to run:

   ```javascript
   module.exports = client;
   ```

