#include <string>
#include <iostream>
#include <boost/algorithm/string.hpp>
#include <boost/algorithm/string/trim.hpp>
#include <boost/algorithm/string/replace.hpp>
#include <boost/algorithm/string/join.hpp>
#include <boost/algorithm/string/split.hpp>
#include <boost/optional.hpp>
#include <boost/regex.hpp>

// A simple Markdown to HTML converter function
std::string markdown_to_html(const std::string& markdown) {
    // Define some HTML tags and attributes
    const std::string strong_tag = "<strong>";
    const std::string strong_end_tag = "</strong>";
    const std::string em_tag = "<em>";
    const std::string em_end_tag = "</em>";
    const std::string paragraph_tag = "<p>";
    const std::string paragraph_end_tag = "</p>";
    const std::string line_break_tag = "<br>";
    const std::string link_open_tag = "<a href='";
    const std::string link_end_tag = "'>";
    const std::string link_close_tag = "</a>";

    // Define some regular expressions for Markdown parsing
    const boost::regex heading_regex("^#{1,6}(.+)$");
    const boost::regex bold_regex("\\*([^\\*]*)\\*");
    const boost::regex italic_regex("_(.+?)_");
    const boost::regex link_regex("\\[\\[(.+?)\\]\\]\\((.+?)\\)");
    const boost::regex paragraph_regex("^([^\\n]*)$");
    const boost::regex line_break_regex("\\n+");

    // Initialize the HTML string
    std::string html;

    // Split the Markdown text into paragraphs
    std::vector<std::string> paragraphs;
    boost::algorithm::split(paragraphs, markdown, boost::is_any_of("\n\n"));

    // Process each paragraph
    for (const auto& paragraph : paragraphs) {
        // Remove leading and trailing whitespaces
        boost::algorithm::trim(paragraph);

        // Replace line breaks with HTML line break tag
        boost::algorithm::replace_all(paragraph, "\n", line_break_tag);

        // Check if the paragraph is a heading
        boost::smatch heading_match;
        if (boost::regex_match(paragraph, heading_match, heading_regex)) {
            std::string level = heading_match[1].str();
            boost::algorithm::replace_all(level, "#", "");
            html += std::string("<h") + level + ">" + heading_match[2].str() + "</h" + level + ">\n";
        } else {
            // Process the paragraph for other Markdown formatting
            std::vector<std::string> tokens;
            boost::algorithm::split(tokens, paragraph, boost::is_any_of(" "));
            std::vector<std::string> modified_tokens;

            for (const auto& token : tokens) {
                // Check if the token is bold
                boost::smatch bold_match;
                if (boost::regex_match(token, bold_match, bold_regex)) {
                    modified_tokens.push_back(strong_tag + bold_match[1] + strong_end_tag);
                    continue;
                }

                // Check if the token is italic
                boost::smatch italic_match;
                if (boost::regex_match(token, italic_match, italic_regex)) {
                    modified_tokens.push_back(em_tag + italic_match[1] + em_end_tag);
                    continue;
                }

                // Check if the token is a link
                boost::smatch link_match;
                if (boost::regex_match(token, link_match, link_regex)) {
                    modified_tokens.push_back(link_open_tag + link_match[2] + link_end_tag + link_match[1] + link_close_tag);
                    continue;
                }

                modified_tokens.push_back(token);
            }

            // Join the modified tokens into a single string
            std::string processed_paragraph = boost::algorithm::join(modified_tokens, " ");

            // Wrap the processed paragraph in HTML paragraph tag
            html += paragraph_tag + processed_paragraph + paragraph_end_tag + "\n";
        }
    }

    return html;
}

int main() {
    std::string markdown = "## Heading\n\nThis is a **bold** text with an _italic_ part.\n\n[Link text](https://example.com)";

    std::string html = markdown_to_html(markdown);

    std::cout << "Markdown:\n" << markdown << "\n\nHTML:\n" << html << std::endl;

    return 0;
}
```

