    snake->body[1].y = snake->body[0].y + snake->dir_y * GRID_SIZE;

    snake->body[2].x = snake->body[1].x + snake->dir_x * GRID_SIZE;
    snake->body[2].y = snake->body[1].y + snake->dir_y * GRID_SIZE;
}

void move_snake(Snake *snake) {
    Point *tail = &snake->body[snake->size - 1];
    Point *head = &snake->body[0];

    head->x += snake->dir_x * GRID_SIZE;
    head->y += snake->dir_y * GRID_SIZE;

    int i;
    for (i = snake->size - 2; I >= 0; --i) {
        snake->body[i + 1] = snake->body[i];
    }

    snake->body[0] = *head;

    if (tail->x == head->x && tail->y == head->y) {
        // Snake collided with itself
        printf("Game over!\n");
        exit(EXIT_FAILURE);
    }
}

void update_snake(SDL_Event *event, Snake *snake) {
