    int frame_count = 0;
    Uint32 start_ticks, end_ticks, interval;

    while (running) {
        start_ticks = SDL_GetTicks();

        while (SDL_PollEvent(&event)) {
            switch (event.type) {
                case SDL_QUIT:
                    running = 0;
                    break;
                case SDL_KEYDOWN:
